      "type": "∀ {R : Type u_1} [inst : CommRing R] {K : Type u_2} [inst_1 : Field K] [inst_2 : Algebra R K] [IsFractionRing R K]\n  [IsDomain R] [Nonempty (NormalizedGCDMonoid R)] {p : Polynomial R},\n  p.IsPrimitive → (Irreducible p ↔ Irreducible (Polynomial.map (algebraMap R K) p))"
